var contentBufPool sync.Pool

func getContentBuf(size int) []byte {
	if v := contentBufPool.Get(); v != nil {
		bp := v.(*[]byte) //nolint:errcheck,forcetypeassert // pool only stores *[]byte
		if cap(*bp) >= size {
			return (*bp)[:size]
		}
		// Undersize. Return it to the pool so smaller future calls can
		// reuse it instead of letting Get's drop-on-miss leak the pool.
		contentBufPool.Put(bp)
	}
	return make([]byte, size)
}

func putContentBuf(b []byte) {
	b = b[:cap(b)]
	contentBufPool.Put(&b)
}

